package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
final class AnswerCorrectionDialog {
 static void show(MainActivity owner,JSONObject source){ReliabilityDialog ui=new ReliabilityDialog(owner);ui.work(()->AnswerCorrections.view(owner,source),entry->{LinearLayout box=ui.box();TextView text=new TextView(owner);text.setTextIsSelectable(true);text.setText(AnswerCorrections.text(entry));box.addView(text);ui.button(box,"この情報は違う・訂正を追加",()->edit(owner,entry));ui.display("元の回答と訂正",box);});}
 static void edit(MainActivity owner,JSONObject entry){ReliabilityDialog ui=new ReliabilityDialog(owner);LinearLayout box=ui.box();ui.text(box,"元の回答は上書きしません。自分の訂正としてスマホに保存します。訂正の訂正は追記してください。AIへは送信しません。");EditText field=ui.field(box,"訂正内容（1〜2400文字）","",2400);ui.button(box,"最新の訂正を別画面で確認（入力は残す）",()->show(owner,entry.optJSONObject("source")));String id=java.util.UUID.randomUUID().toString();AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("回答への訂正").setView(OfflineAccess.scroll(owner,box)).setPositiveButton("訂正を保存",null).setNegativeButton("戻る",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{String value=field.getText().toString();if(value.trim().isEmpty()){field.setError("訂正内容を入力してください");return;}dialog.getButton(-1).setEnabled(false);new Thread(()->{try{JSONObject input=new JSONObject().put("source",entry.getJSONObject("source")).put("revision",entry.getInt("revision")).put("changeId",id).put("text",value);JSONObject saved=AnswerCorrections.submit(owner,input);owner.runOnUiThread(()->{if(owner.isDestroyed())return;dialog.dismiss();show(owner,saved.optJSONObject("source"));});}catch(Exception e){owner.runOnUiThread(()->{if(owner.isDestroyed()||!dialog.isShowing())return;dialog.getButton(-1).setEnabled(true);field.setError(e.getMessage()==null?"保存できません。入力は残しています":e.getMessage());});}},"AnswerCorrectionSave").start();}));dialog.show();}
 static void library(MainActivity owner){ReliabilityDialog ui=new ReliabilityDialog(owner);ui.work(()->new JSONObject().put("items",AnswerCorrections.list(owner)),data->{LinearLayout box=ui.box();ui.text(box,"元の回答のコピーと、自分が保存した訂正です。AIが訂正の正しさを確認したものではありません。");JSONArray rows=data.optJSONArray("items");if(rows.length()==0)ui.text(box,"訂正付き回答はまだありません。保存済み回答から追加できます。");for(int i=0;i<rows.length();i++){JSONObject entry=rows.optJSONObject(i),source=entry.optJSONObject("source");String body=source.optString("message");ui.button(box,"訂正 "+entry.optInt("revision")+"件 / "+new java.util.Date(source.optLong("time"))+"\n"+body.substring(0,Math.min(70,body.length())),()->show(owner,source));}ui.display("訂正付き回答",box);});}
 private AnswerCorrectionDialog(){}
}
